          setImperativeOptions(null)
          afterHide?.()
        }}
        style={tooltipStyle}
        ref={tooltipRef}
      >
        <WrapperElement
          className={clsx(
            'react-tooltip-content-wrapper',
            coreStyles['content'],
            styles['content'],
          )}
        >
          {actualContent}
        </WrapperElement>

